package android.util;public class Pair<F,S>{public final F first;public final S second;public Pair(F f,S s){first=f;second=s;}public static <A,B> Pair<A,B> create(A a,B b){return new Pair<>(a,b);}public boolean equals(Object o){if(!(o instanceof Pair))return false;Pair<?,?> p=(Pair<?,?>)o;return java.util.Objects.equals(first,p.first)&&java.util.Objects.equals(second,p.second);}public int hashCode(){return java.util.Objects.hashCode(first)^java.util.Objects.hashCode(second);}}